\u0057\u0061\u0051\u0034\u0024\u0066\u004d\u0052\u0069\u007b\u005e\u0031\u0038\u004b\u0062\u003d\u0028\u007d\u005e\u005e\u006a\u0054\u0055\u0030\u0071\u004b\u003a\u0021\u0048\u0042\u0066\u0022\u005f\u0073\u0034\u004d\u006b\u0062\u0033\u007b\u0021\u004e\u0040\u007a\u002b\u005b\u0036\u004f\u0038\u006b\u0054\u006e\u0024\u0034\u006f\u003b\u003f\u006f\u007d\u004a\u0047\u004c\u0056\u0036\u005e\u0067\u0065\u0047\u003e\u0060\u004a\u0078\u005d\u006e\u0021\u005e\u0045\u0042\u0074\u005a\u004a\u006c\u0036\u0062\u006b\u0029\u0031\u0076\u002f\u0033\u0072\u0024\u0062\u0077\u0065\u0037\u0024\u0057\u006c\u005e\u006e\u0048\u0035\u0063\u0031\u0031\u0064\u0043\u005a\u0071\u0071\u0023\u0060\u0055\u004b\u0074\u0021\u002a\u005f\u005d\u006f\u004f\u003a\u006c\u0055\u004e\u0048\u0068\u005e\u003a\u003c\u0052\u0034\u0052\u0068\u006d\u005e\u0055\u0075\u0036\u0045\u0075\u004d\u0041\u007a\u0055\u0033\u0029\u002c\u002c\u006d\u005d\u0038\u002a\u007e\u0070\u006c\u0068\u0052\u0043\u0047\u004e\u0051\u0043\u0044\u0055\u006f\u007d\u004a\u0047\u004c\u0056\u0069\u0054\u006a\u0037\u0038\u0033\u0075\u0028\u0076\u002c\u005f\u0048\u0051\u0031\u0031\u007d\u0046\u0037\u0073\u0050\u0035\u0059\u0051\u005b\u0050\u0043\u0067\u007d\u0070\u0070\u003d\u004a\u0074\u0031\u0079\u0050\u0041\u003b\u007e\u0037\u003c\u0060\u002e\u0059\u0024\u0065\u0078\u007a\u003c\u0073\u0039\u0056\u0068\u0068\u0061\u0026\u007e\u0063\u0043\u0053\u0057\u0047\u0075\u0073\u0047\u0079\u006b\u0063\u0043\u006d\u005e\u003f\u0042\u006c\u0034\u0070\u0024\u0063\u0021\u003e\u0043\u0034\u004a\u0025\u0045\u007b\u005e\u004f\u0050\u0048\u0048\u0066\u0040\u004a\u0078\u006b\u004e\u0029\u0066\u0036\u0045\u007e\u006a\u0028\u003f\u004f\u0034\u007a\u0024\u0065\u0078\u0064\u0074\u0074\u002c\u005e\u006b\u0064\u0063\u0054\u003c\u0031\u0064\u0030\u0070\u0063\u0021\u0023\u0076\u005e\u0039\u0064\u0031\u0058\u0048\u0074\u003c\u0039\u006a\u006b\u0021\u004c\u0078\u004f\u0054\u0041\u004a\u0061\u0045\u007b\u005e\u0031\u007e\u0043\u0043\u0034\u007a\u0047\u0075\u005d\u0036\u003f\u005d\u006c\u0049\u0029\u0058\u007d\u006c\u0045\u0046\u002b\u005d\u004c\u004f\u0061\u004d\u0079\u0038\u002f\u0058\u0064\u0039\u0037\u0070\u0028\u0067\u0052\u0038\u002f\u0037\u0045\u006e\u0021\u0042\u003f\u0057\u002b\u004f\u0075\u003f\u0047\u003f\u002b\u0058\u006c\u0056\u0023\u005e\u0021\u003f\u0064\u0031\u0079\u0028\u0067\u004b\u004b\u0045\u0022\u0065\u0035\u003d\u002a\u0078\u0051\u0071\u005a\u0070\u0063\u0079\u0054\u0058\u004c\u003f\u0072\u0072\u007c\u007d\u0044\u0070\u0046\u0078\u0061\u002a\u0042\u0058\u0078\u0065\u004e\u0021\u0028\u0070\u0079\u002c\u006e\u0072\u003c\u0034\u0053\u0067\u0037\u0041\u0036\u004e\u0072\u0049\u004a\u004c\u006b\u006f\u0074\u0048\u0040\u004b\u0023\u0066\u003b\u006e\u0058\u0037\u0071\u0042\u0048\u0069\u0037\u0039\u0022\u0079\u0079\u0054\u005e\u002f\u0056\u0056\u007b\u0052\u0077\u0073\u0033\u0063\u005f\u002b\u0059\u003c\u002c\u0058\u0058\u0071\u005f\u002a\u002b\u004f\u0061\u007d\u004a\u0040\u0031\u003a\u0073\u005e\u0058\u0071\u0059\u002a\u0077\u0075\u0028\u003d\u0022\u0058\u0032\u004a\u0044\u0030\u0036\u006f\u0066\u006c\u0078\u0028\u0031\u0022\u0026\u004f\u0052\u002a\u004a\u0049\u0021\u003c\u0022\u0038\u0046\u0046\u006a\u007c\u0072\u0065\u0067\u0031\u0059\u0071\u0068\u0060\u007a\u0064\u0054\u0033\u0053\u0032\u0060\u002f\u003e\u0030\u0045\u0058\u0053\u0071\u004b\u0041\u0041\u0021\u005f\u007b\u007b\u004f\u007e\u0069\u005e\u006a\u007d\u0035\u002b\u0056\u006f\u0068\u0078\u0046\u0067\u007b\u004f\u0034\u006e\u0039\u0075\u005b\u003e\u004b\u004b\u0039\u0046\u0041\u0045\u0043\u006a\u0025\u0079\u0048\u0071\u0076\u007c\u0030\u0058\u006f\u0072\u003d\u002a\u0029\u004c\u0025\u004b\u007c\u0037\u0075\u0067\u005e\u0039\u0022\u0070\u0043\u0038\u002c\u0043\u004e\u0025\u0024\u0029\u0022\u0050\u0059\u0034\u0078\u0021\u0042\u0026\u0078\u0024\u003d\u0049\u004e\u0047\u0071\u0079\u0079\u0043\u003e\u0048\u0064\u0042\u0065\u006f\u0043\u0034\u0025\u0064\u0056\u0029\u0073\u002e\u0033\u0053\u0064\u004a\u0038\u0038\u0053\u005f\u006d\u004f\u006b\u0072\u0028\u007a\u0076\u005e\u007b\u0064\u006d\u0024\u004d\u002b\u0074\u0075\u003d\u003e\u006d\u0052\u0026\u0028\u0040\u0059\u005b\u0031\u0075\u0077\u0078\u0024\u0051\u005f\u0029\u0060\u007b\u004f\u006c\u005b\u005a\u006c\u0033\u0029\u003c\u003c\u002c\u003c\u0079\u0025\u0045\u003f\u0070\u006f\u0028\u0075\u0046\u007a\u0050\u003f\u005d\u0056\u0077\u0052\u0047\u0061\u0026\u0055\u006f\u0054\u0042\u003d\u0033\u0060\u002e\u0025\u0032\u0061\u005e\u0056\u0065\u0021\u0064\u0052\u0076\u0059\u0063\u0037\u003f\u0032\u0037\u0079\u0079\u0068\u0036\u0059\u004d\u007a\u003c\u0038\u0043\u0047\u0044\u005f\u005b\u0063\u0025\u0061\u0062\u002c\u004c\u0029\u0075\u0033\u002c\u0074\u002e\u0029\u0057\u006c\u005a\u0072\u0078\u0023\u005d\u0022\u006f\u0043\u0068\u0034\u0030\u003d\u0075\u0028\u0065\u0071\u0028\u004f\u004f\u0035\u0050\u005d\u0040\u004e\u003c\u0061\u006f\u005d\u002a\u006f\u0077\u0077\u0028\u0038\u004a\u0032\u006d\u0068\u003e\u0070\u0049\u0025\u0061\u0062\u002c\u004c\u0029\u004b\u0071\u0077\u0039\u007a\u0063\u003b\u004b\u004f\u002c\u0032\u0069\u0024\u0037\u0076\u0049\u003c\u002b\u0063\u0058\u0056\u004e\u0029\u007c\u005b\u005d\u0022\u004f\u0075\u0028\u003b\u0051\u0059\u006f\u0059\u0043\u0062\u003b\u0063\u005e\u0021\u0049\u0047\u0047\u007e\u007c\u0068\u0053\u0053\u0055\u004b\u0034\u004c\u0061\u0029\u0077\u0075\u003f\u004b\u005b\u006c\u0044\u0034\u0073\u0030\u0055\u0034\u006d\u004a\u006d\u0057\u007b\u0026\u0044\u004d\u0062\u002a\u0073\u0039\u006c\u0055\u003f\u006c\u006e\u0062\u002b\u004e\u004f\u004f\u0044\u003d\u0030\u006d\u0043\u0072\u007e\u0030\u0026\u005b\u0058\u0029\u0069\u0038\u0066\u0060\u0040\u003a\u0028\u0055\u002f\u0075\u0022\u007b\u0078\u006b\u006a\u0063\u0046\u0034\u007d\u002f\u003e\u0073\u004b\u003f\u005b\u0029\u004b\u003c\u0079\u002c\u0021\u003a\u0042\u0052\u004c\u0068\u0028\u0033\u006f\u0049\u006f\u007a\u0057\u0021\u005d\u0029\u003e\u004e\u0029\u0059\u004d\u0052\u0026\u004d\u007e\u005a\u004e\u005e\u0046\u004a\u0038\u0028\u004e\u0048\u0048\u0049\u003e\u007d\u0038\u0026\u0062\u0032\u0064\u0037\u006f\u0021\u0050\u0078\u0047\u0075\u0059\u0042\u0055\u004d\u0049\u007a\u006c\u0076\u004a\u0031\u0062\u0022\u004e\u005e\u003a\u006e\u0021\u002c\u005b\u003e\u0077\u0046\u0059\u0033\u0069\u0076\u004d\u007e\u0067\u0039\u006f\u0049\u0035\u0057\u003a\u003c\u0064\u0074\u004e\u002a\u0064\u0067\u007b\u0062\u0040\u004a\u0068\u007e\u0022\u006f\u005a\u0047\u0030\u0024\u0050\u0032\u0069\u003a\u003a\u003f\u007a\u006c\u004c\u006f\u0076\u003e\u0036\u003f\u0038\u006f\u0063\u007a\u004a\u0063\u0044\u005b\u002f\u0067\u005e\u0060\u0064\u0053\u002a\u003c\u0055\u004b\u002a\u0064\u005a\u007e\u006a\u0078\u0040\u004c\u0024\u0055\u004a\u0074\u004b\u0075\u004b\u0074\u003c\u003c\u0029\u0034\u002a\u0058\u0058\u0051\u0026\u0071\u0066\u005f\u0034\u0029\u005a\u0050\u005b\u0078\u0026\u0063\u0030\u0045\u0058\u0053\u0071\u004b\u0041\u0028\u0079\u002b\u002a\u0058\u0022\u003a\u0034\u002f\u0067\u0033\u0029\u0065\u0079\u0022\u0044\u0030\u0024\u0072\u003a\u004b\u0042\u004c\u005a\u0072\u0026\u004d\u0034\u0034\u004c\u0062\u0040\u0075\u0051\u0076\u003b\u003d\u003f\u006b\u0031\u0030\u0077\u002b\u0036\u005d\u0034\u004b\u0043\u002c\u005d\u003e\u0025\u0042\u0072\u0060\u0029\u003c\u0034\u0025\u007b\u003a\u0044\u002f\u006a\u004e\u0070\u007a\u003c\u0036\u004e\u0021\u005a\u003f\u0053\u0035\u0070\u0038\u0025\u0072\u0023\u0057\u003d\u0023\u0051\u0060\u0058\u0045\u004e\u0025\u0033\u0073\u0036\u0059\u0037\u0022\u0042\u0061\u0070\u0023\u005f\u0067\u0063\u004f\u0034\u0029\u0076\u006a\u0078\u0064\u0021\u004e\u007c\u0032\u0063\u004c\u0034\u0070\u0064\u0052\u007e\u0037\u0063\u007e\u004f\u0070\u0057\u0037\u006f\u007a\u0053\u0077\u0076\u0061\u0048\u0042\u0028\u004a\u0030\u0022\u0069\u007d\u006b\u0021\u0052\u0058\u006e\u004f\u0043\u0024\u007e\u002e\u003c\u004d\u0023\u0036\u0064\u0060\u0064\u005d\u0047\u0029\u0072\u0072\u0039\u004d\u007e\u003c\u0079\u0078\u002f\u0063\u007a\u0046\u0033\u0024\u003f\u004c\u003c\u005e\u0043\u006f\u0043\u0021\u0035\u0045\u0049\u0066\u007e\u0053\u0030\u0033\u0028\u0056\u003d\u0067\u0076\u005b\u006f\u003c\u0074\u0044\u0070\u0056\u002f\u0024\u007a\u0033\u0028\u0056\u004d\u004f\u005a\u004c\u0069\u0067\u0033\u0043\u006a\u004c\u007e\u007b\u002b\u0052\u0070\u0079\u0049\u0052\u0075\u0065\u0067\u0034\u0035\u0061\u0068\u0033\u0078\u005e\u0055\u0041\u007b\u0065\u0067\u0033\u0030\u0070\u007c\u0025\u0030\u004b\u003f\u007e\u0026\u002e\u0057\u003d\u0078\u0055\u002b\u002b\u0033\u0073\u0073\u005a\u003f\u004c\u002b\u0028\u0067\u003d\u004b\u0025\u003d\u007e\u002e\u0055\u005b\u0061\u0054\u0058\u0054\u0033\u0038\u004b\u0035\u004e\u006b\u0032\u002c\u003d\u004f\u0054\u0059\u0068\u0033\u0032\u005a\u003f\u0075\u0033\u007a\u004e\u007d\u0070\u007b\u0032\u0025\u0062\u0052\u0032\u005d\u0075\u0023\u0069\u0052\u0067\u007d\u0043\u0029\u005f\u0069\u007a\u0075\u0065\u002b\u0070\u0061\u005e\u005e\u0023\u006d\u006d\u006b\u0024\u002b\u0060\u005b\u0054\u007c\u0056\u0049\u0059\u0057\u002e\u006d\u004f\u0040\u0054\u0023\u0029\u0031\u0029\u004b\u0056\u007e\u003c\u0079\u0078\u002f\u0063\u0041\u0029\u006e\u0051\u0026\u003b\u0042\u0073\u0052\u0075\u0065\u0067\u0034\u0035\u0061\u0068\u0055\u0059\u0021\u0066\u0064\u0023\u005e\u004e\u0071\u0057\u004c\u002b\u0032\u0077\u0068\u003b\u005a\u0034\u0033\u0037\u0033\u002c\u003d\u0075\u0026\u002e\u0049\u0045\u0031\u004f\u0032\u0070\u0059\u002c\u002c\u0037\u0078\u004c\u002f\u007e\u006e\u0032\u006b\u005b\u004e\u0042\u0066\u0030\u0039\u002c\u0068\u0045\u0048\u0038\u003e\u0071\u005b\u002e\u003d\u0070\u0028\u0055\u002a\u0075\u004a\u0059\u0053\u0045\u005d\u0078\u0049\u0041\u0035\u0035\u0078\u0052\u004b\u0021\u0054\u0077\u003f\u0059\u0031\u0072\u0058\u004c\u0053\u0075\u0066\u0070\u004c\u002b\u0073\u0061\u006f\u0054\u0029\u0045\u0057\u0023\u0053\u003d\u004b\u0031\u005d\u0022\u0023\u0031\u004f\u003c\u0076\u007b\u0079\u0067\u003c\u0021\u007c\u0037\u0033\u0040\u0039\u005d\u004e\u0039\u005e\u002c\u0059\u0051\u0028\u0077\u0044\u0034\u0053\u0039\u0037\u0054\u0044\u0067\u0065\u007e\u0062\u002c\u0055\u0064\u004c\u006d\u002e\u006d\u0040\u0041\u0028\u0079\u0041\u0063\u0061\u004a\u004b\u0036\u007b\u003d\u0055\u0035\u0070\u0079\u007d\u0034\u004f\u0038\u0063\u0079\u0032\u0067\u003d\u0052\u0043\u0037\u003c\u0044\u004a\u007a\u005b\u0048\u003b\u0062\u0038\u0045\u006c\u0046\u003d\u0057\u0032\u0034\u0023\u0044\u0028\u006a\u003a\u0075\u0035\u0058\u002f\u004d\u0030\u003a\u0021\u003c\u006c\u006c\u0022\u0023\u0068\u0054\u003b\u0030\u003d\u006d\u003c\u0071\u003c\u005a\u005f\u0059\u0042\u0045\u007c\u0046\u006b\u0071\u002f\u002b\u0042\u0033\u0037\u004b\u005d\u0062\u003f\u0075\u0028\u0037\u006b\u0067\u0034\u0022\u0047\u0038\u006b\u004b\u0062\u003b\u004d\u002e\u0040\u007d\u0068\u0026\u0055\u0056\u0076\u0056\u005e\u0042\u0024\u004d\u0075\u0071\u002c\u0036\u0043\u0053\u0029\u003c\u0055\u0023\u0061\u0050\u0059\u0037\u0037\u007a\u0066\u0040\u0078\u002b\u0060\u0046\u0062\u0029\u004b\u0036\u0072\u0072\u003a\u0042\u0078\u0024\u0026\u0049\u0036\u002c\u0072\u0031\u0036\u0069\u0025\u0036\u0063\u002f\u0041\u0042\u0024\u006b\u0057\u005d\u0052\u004d\u0022\u0064\u0024\u0039\u005b\u002b\u0071\u0046\u0074\u007d\u0059\u0063\u004e\u0044\u004f\u004f\u007a\u003c\u004c\u004d\u006c\u0052\u002e\u002e\u0047\u0062\u0039\u0056\u0073\u004f\u002a\u004b\u002e\u0050\u0041\u0046\u0064\u0067\u0066\u0037\u0060\u005e\u0041\u0042\u0042\u0037\u0065\u0040\u0029\u003d\u0039\u0064\u0064\u0021\u0079\u0055\u0071\u0068\u0042\u0059\u005a\u0035\u003b\u0047\u0039\u004d\u0075\u007e\u0063\u005d\u004e\u006d\u005e\u0036\u007b\u005e\u004d\u002e\u002c\u003b\u0043\u006a\u0051\u0042\u0057\u004d\u0034\u0033\u004e\u0022\u0071\u0078\u004c\u004e\u006d\u005e\u004e\u002a\u004d\u007c\u0054\u003c\u004c\u0030\u003d\u005f\u0053\u0021\u0034\u0023\u007e\u003e\u0068\u0067\u006e\u007c\u0040\u003d\u0069\u0060\u0030\u0042\u0022\u0078\u0055\u0023\u0025\u006c\u0062\u0037\u0073\u0048\u0031\u0038\u007a\u0054\u003e\u002c\u0026\u0069\u002b\u0055\u006b\u0032\u006e\u0076\u0046\u0049\u0045\u0037\u0030\u0076\u0054\u0028\u004a\u005f\u0050\u0060\u007c\u0024\u0028\u003d\u0021\u0067\u0061\u0051\u0077\u0038\u003b\u003f\u0024\u0030\u004f\u0032